package juegohilos;

import java.util.EnumMap;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.Clip;
import javax.sound.sampled.LineEvent;

/**
 * Sound effects generated by code (no audio files needed).
 * Sound-Thread takes effects from a queue and plays them, so audio never slows the game down.
 */
public final class Sonido {

    public enum Efecto {
        STAR, BOMB, VOWEL, COMPLETE, POWERUP, TICK, WARNING,
        GAMEOVER, RECORD, START, MENU_OPEN, MENU_CLOSE, MOVE, SELECT, READY
    }

    private static final float RATE = 22050f;
    private static final AudioFormat FORMATO = new AudioFormat(RATE, 16, 1, true, false);
    private static final Random RND = new Random();
    private static final Map<Efecto, byte[]> BANCO = new EnumMap<>(Efecto.class);
    private static final BlockingQueue<Efecto> COLA = new LinkedBlockingQueue<>();

    private static volatile boolean disponible = true;
    private static volatile boolean silencio = false;
    private static boolean iniciado = false;

    private Sonido() { }

    public static synchronized void iniciar() {
        if (iniciado) return;
        iniciado = true;
        construirBanco();
        Thread t = new Thread(Sonido::bucleEfectos, "Sound-Thread");
        t.setDaemon(true);
        t.start();
    }

    public static void reproducir(Efecto e) {
        if (!silencio && disponible) COLA.offer(e);
    }

    public static void setSilencio(boolean valor) { silencio = valor; }

    public static boolean isSilencio() { return silencio; }

    /** shape: 0 = square, 1 = triangle, 2 = noise. Frequency slides from f0 to f1. */
    private static byte[] tono(double f0, double f1, double seg, double vol, int forma) {
        int n = (int) (RATE * seg);
        byte[] out = new byte[n * 2];
        double fase = 0;
        for (int i = 0; i < n; i++) {
            double t = (double) i / n;
            double f = f0 + (f1 - f0) * t;
            fase += 2 * Math.PI * f / RATE;
            double v;
            switch (forma) {
                case 0:  v = Math.sin(fase) >= 0 ? 1 : -1; break;
                case 1:  v = 2 / Math.PI * Math.asin(Math.sin(fase)); break;
                default: v = RND.nextDouble() * 2 - 1;
            }
            double env = (1 - t) * Math.min(1.0, i / 80.0);
            short s = (short) (v * env * vol * 32767);
            out[2 * i] = (byte) (s & 0xFF);
            out[2 * i + 1] = (byte) ((s >> 8) & 0xFF);
        }
        return out;
    }

    private static byte[] unir(byte[]... partes) {
        int total = 0;
        for (byte[] p : partes) total += p.length;
        byte[] out = new byte[total];
        int pos = 0;
        for (byte[] p : partes) {
            System.arraycopy(p, 0, out, pos, p.length);
            pos += p.length;
        }
        return out;
    }

    private static void construirBanco() {
        BANCO.put(Efecto.STAR, unir(tono(880, 880, 0.05, 0.22, 0), tono(1318, 1318, 0.10, 0.22, 0)));
        BANCO.put(Efecto.BOMB, unir(tono(0, 0, 0.10, 0.40, 2), tono(200, 50, 0.28, 0.35, 0)));
        BANCO.put(Efecto.VOWEL, unir(tono(587, 587, 0.06, 0.25, 1), tono(784, 784, 0.06, 0.25, 1),
                tono(988, 988, 0.10, 0.25, 1)));
        BANCO.put(Efecto.COMPLETE, unir(tono(523, 523, 0.07, 0.22, 0), tono(659, 659, 0.07, 0.22, 0),
                tono(784, 784, 0.07, 0.22, 0), tono(1047, 1047, 0.07, 0.22, 0), tono(1319, 1319, 0.25, 0.22, 0)));
        BANCO.put(Efecto.POWERUP, tono(300, 900, 0.25, 0.22, 0));
        BANCO.put(Efecto.TICK, tono(1000, 1000, 0.03, 0.12, 0));
        BANCO.put(Efecto.WARNING, tono(440, 440, 0.10, 0.25, 0));
        BANCO.put(Efecto.GAMEOVER, unir(tono(440, 440, 0.18, 0.30, 0), tono(370, 370, 0.18, 0.30, 0),
                tono(311, 311, 0.18, 0.30, 0), tono(262, 180, 0.55, 0.30, 0)));
        BANCO.put(Efecto.RECORD, unir(tono(523, 523, 0.10, 0.25, 0), tono(659, 659, 0.10, 0.25, 0),
                tono(784, 784, 0.10, 0.25, 0), tono(1047, 1047, 0.40, 0.25, 0)));
        BANCO.put(Efecto.START, unir(tono(392, 392, 0.07, 0.22, 0), tono(523, 523, 0.07, 0.22, 0),
                tono(659, 659, 0.07, 0.22, 0), tono(784, 784, 0.15, 0.22, 0)));
        BANCO.put(Efecto.MENU_OPEN, tono(400, 700, 0.10, 0.20, 0));
        BANCO.put(Efecto.MENU_CLOSE, tono(700, 400, 0.10, 0.20, 0));
        BANCO.put(Efecto.MOVE, tono(600, 600, 0.04, 0.18, 0));
        BANCO.put(Efecto.SELECT, unir(tono(800, 800, 0.05, 0.20, 0), tono(1100, 1100, 0.08, 0.20, 0)));
        BANCO.put(Efecto.READY, unir(tono(659, 659, 0.08, 0.22, 0), tono(880, 880, 0.08, 0.22, 0),
                tono(1175, 1175, 0.20, 0.22, 0)));
    }

    private static void bucleEfectos() {
        while (true) {
            try {
                Efecto e = COLA.take();
                if (!disponible) continue;
                byte[] datos = BANCO.get(e);
                Clip clip = AudioSystem.getClip();
                clip.open(FORMATO, datos, 0, datos.length);
                clip.addLineListener(ev -> {
                    if (ev.getType() == LineEvent.Type.STOP) clip.close();
                });
                clip.start();
            } catch (InterruptedException ex) {
                return;
            } catch (Exception | Error ex) {
                disponible = false; // no audio device: the game keeps running silently
            }
        }
    }
}
